// Cover (slide 0) dot-matrix mark animator.
//
// Reads window.APOLLO_DOTS (generated by tools/dot_mark.py) and animates the ring + A dots
// through the approved 11.6 s loop:
//
//   0.0–0.5 s   dot alone at the ring's gap (head sits still)
//   0.5–4.1 s   head laps the ring twice (cubic in-out); on lap 2 ring dots light up as
//               the head sweeps past (arrive from the lattice behind the head and spring
//               into their grid position)
//   3.3–4.6 s   the A assembles: dots pop in one by one in a random order (spring scale,
//               small settle from a jitter offset)
//   4.75–6.85 s REST. One magnet front traverses the mark in ~2.1 s (eased). Every dot
//               answers it on its own: a per-dot damped spring with its own lag, gain,
//               snap threshold, stiffness, damping and lean angle, so dots rise, peak and
//               rebound at different moments, like separate pieces of metal (not a sheet).
//               Settles by ~7.8 s. Optional pointer magnet until the A dissolve starts.
//   7.25–8.20 s the A dissolves: dots shrink and fade one by one in a different random order
//               (0.70 s spread + 0.25 s each); the A is completely gone by 8.20 s
//   8.30–9.40 s the agent reels the ring back in: the clear front starts at the far end of
//               the arc (the gap's lower lip) and runs back to the head dot, so the line is
//               pulled into it. Each dot drifts up to one pitch toward the head while it
//               shrinks and fades (the front is scaled so even the last dot, beside the
//               head, is fully gone at 9.40 s). The head swallows once as the front reaches
//               it (9.25–9.40: radius 1 → 1.12 → 1 and a halo brighten). Starts only after
//               the A has gone.
//   9.40–9.55 s dot alone (no eyes). Every ring/A dot is at its t=0 state by 9.40 s, so the
//               wrap is seamless.
//   9.55–11.45 s the AGENT phase: the lone head dot wakes: it grows to 2.8× and two navy pill
//               eyes open half-lidded, look at the viewer, then widen as it realises (small
//               3% pop). It looks down-left to where the logo was (nothing there), traces
//               down → right along where the ring was, snaps back to the viewer (double-take),
//               blinks once, narrows to a focused look along the lap direction (up-left),
//               closes its eyes and shrinks to the plain dot. (Eyes never appear in motion.)
//   11.45–11.6 s dot alone again, then restart (0–0.5 s: still the plain dot) and the lap
//               re-creates the whole mark.
//   The first visit (each time the cover becomes active) starts the clock at 9.45 s, so the
//   audience sees the dot wake up first and then set off on its lap.
//
// Drawing surface: the canvas (and the still) extend PAD units past the 200-unit viewBox on
// every side, so the outer ring, crest swell, wave/pointer displacement and the head halo
// are never clipped; the mark itself keeps its size and position.
//
// Debug hook: `?covert=SECONDS` freezes the loop at that time (inert without the param) and
// publishes window.__coverStats (and canvas data-covert-stats) for deterministic frame checks.
//
// Pause rules: the loop pauses when the slide isn't .is-active, when the tab is hidden,
// when prefers-reduced-motion is set, or when APOLLO_DOTS isn't loaded. In every paused
// case the static <img class="dot-still"> stays visible under the canvas (never cleared)
// so the resting state is also the final state (print, presenter and reduced-motion all
// honest).
(function () {
  "use strict";

  const CYCLE = 11600; // ms
  const FIRST_VISIT_TS = 9.45; // s: the clock starts here when the cover becomes active
  const MARK_UNITS = 200; // the mark itself is 200×200 SVG units
  const PAD = 16;         // drawing margin per side, in SVG units (8%); matches tools/dot_mark.py PAD
  const PX_IN_SVG = MARK_UNITS + 2 * PAD; // canvas viewport: 232 units
  const covertParam = new URLSearchParams(location.search).get("covert");
  const COVERT = covertParam !== null && covertParam !== "" && isFinite(+covertParam)
    ? ((+covertParam % 11.6) + 11.6) % 11.6 : null;
  const DPR = Math.min(2, window.devicePixelRatio || 1);

  const COL_WHITE = [255, 255, 255];
  const COL_CYAN = [111, 214, 255];   // #6fd6ff
  const COL_LABEL = [170, 203, 255];  // #aacbff

  // ── timeline helpers (same beats as the pre-dot cover_keyframes.py) ───────
  function clamp01(x) { return x < 0 ? 0 : x > 1 ? 1 : x; }
  function ramp(t, a, b) { return clamp01((t - a) / (b - a)); }
  function cio(t) { // cubic in-out on 0..1
    t = clamp01(t);
    return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
  }
  function lapProgress(ts) { return cio(ramp(ts, 0.5, 4.1)); }
  // A ring dot fades over 1/18 of the arc as the draw / clear front passes it. Both fronts are
  // scaled by (1 + 1/18) so the front clears the last dot (d = 1) by a full fade width:
  // fully lit when drawn, fully gone when cleared (no residual alpha on the arc's last dots).
  const FRONT_SOFT = 1 / 18;
  function ringDrawn(ts) { return clamp01((lapProgress(ts) - 0.5) * 2) * (1 + FRONT_SOFT); }
  // Clear front, measured from the far end (d = 1) back toward the head (d = 0): a dot is gone once it passes 1 − d.
  function ringClear(ts) { return cio(ramp(ts, 8.3, 9.4)) * (1 + FRONT_SOFT); }
  // A dots arrive and leave one by one, each at its own random moment. The order is a stable
  // hash of the dot index (in and out use different orders), so every loop repeats cleanly
  // and ?covert= frames are deterministic.
  const A_IN_START = 3.3, A_IN_SPREAD = 1.0, A_IN_DUR = 0.32;     // every A dot is in by 4.62 s
  const A_OUT_START = 7.25, A_OUT_SPREAD = 0.70, A_OUT_DUR = 0.25; // every A dot is out by 8.20 s
  function hash01(n) { const s = Math.sin(n * 127.1 + 311.7) * 43758.5453; return s - Math.floor(s); }
  function backOut(t) { const c = 1.9; t = clamp01(t) - 1; return 1 + (c + 1) * t * t * t + c * t * t; }

  // ── Agent phase: the lone head dot wakes, realises the mark is gone, goes back to work ──
  const AG_START = 9.55, AG_DUR = 1.9;
  const AG_GROW = 2.8;                // orb radius at full size, × the head dot
  const AG_EYE_COL = "#0b1133";       // the deck's deep navy
  const AG_EYE_W = 3.5, AG_EYE_H = 7.0, AG_EYE_GAP = 7.4, AG_EYE_DY = -0.8; // units at AG_GROW
  const AG_LOOK = 4.0;                // max eye travel inside the orb, units at AG_GROW
  const AG_LAP_LOOK = 0.6;            // the "back to work" look along the lap direction, × AG_LOOK
  const AG_HALF = 0.55, AG_WIDE_BUMP = 0.15, AG_FOCUS = 0.7; // eye scaleY: half-lidded, widen overshoot, focused
  const SWALLOW_START = 9.25, SWALLOW_END = 9.40; // the head gulps as the clear front reaches it
  const ABSORB_MAX = 9;               // max drift of a dot toward the head while it is reeled in, units (≈ 1 pitch)
  const SWALLOW_R = 0.12;             // head radius gain at the gulp's peak
  function easeOut3(t) { t = clamp01(t); return 1 - Math.pow(1 - t, 3); }
  function easeIn2(t) { t = clamp01(t); return t * t; }
  function backOutSoft(t) { const c = 1.4; t = clamp01(t) - 1; return 1 + (c + 1) * t * t * t + c * t * t; }
  function swallow(ts) { return Math.sin(Math.PI * ramp(ts, SWALLOW_START, SWALLOW_END)); } // 0 → 1 → 0
  // Everything the agent draws at ts, or null outside the phase. Look vectors are in units at
  // AG_GROW; (0,0) is "at the viewer". `down` goes toward the mark's centre, `sweep` toward the
  // ring's bottom-right (the gap's lower lip), `lap` along the lap direction from the head.
  function agentState(ts, down, sweep, lap) {
    const tau = ts - AG_START;
    if (tau <= 0 || tau >= AG_DUR) return null;
    // Orb radius (× head dot): wake with a small overshoot, 3% pop on the realisation,
    // hold, shrink back exactly to 1.
    const pop = 1 + 0.03 * Math.sin(Math.PI * ramp(tau, 0.48, 0.60));
    const k = tau < 1.62 ? (1 + (AG_GROW - 1) * backOutSoft(tau / 0.30)) * pop
                         : 1 + (AG_GROW - 1) * (1 - cio((tau - 1.62) / 0.28));
    // Eye scaleY: opens half-lidded 0.18–0.30, widens to full with an overshoot 0.48–0.60,
    // one blink 1.33–1.45, narrows to focused 1.45–1.60, closes 1.55–1.70.
    const wide = ramp(tau, 0.48, 0.60);
    let open = easeOut3((tau - 0.18) / 0.12) * (AG_HALF + (1 - AG_HALF) * easeOut3(wide) + AG_WIDE_BUMP * Math.sin(Math.PI * wide));
    open *= 1 - (1 - AG_FOCUS) * cio(ramp(tau, 1.45, 1.60));
    if (tau > 1.33 && tau < 1.45) open *= 1 - 0.9 * Math.sin(Math.PI * (tau - 1.33) / 0.12);
    open *= 1 - easeIn2((tau - 1.55) / 0.15);
    // Look path: viewer → down-left (nothing there) → sweep down/right → viewer → along the lap.
    const d1 = [down[0] * AG_LOOK, down[1] * AG_LOOK];
    const d2 = [sweep[0] * AG_LOOK, sweep[1] * AG_LOOK];
    const d3 = [lap[0] * AG_LOOK * AG_LAP_LOOK, lap[1] * AG_LOOK * AG_LAP_LOOK];
    let lx = 0, ly = 0, sq = 0, sqDir = down;
    if (tau < 0.60) { /* viewer */ }
    else if (tau < 0.72) { const e = cio((tau - 0.60) / 0.12); lx = d1[0] * e; ly = d1[1] * e; sq = Math.sin(Math.PI * (tau - 0.60) / 0.12); }
    else if (tau < 0.95) { lx = d1[0]; ly = d1[1]; }
    else if (tau < 1.07) {
      const e = cio((tau - 0.95) / 0.12);
      lx = d1[0] + (d2[0] - d1[0]) * e; ly = d1[1] + (d2[1] - d1[1]) * e;
      sq = Math.sin(Math.PI * (tau - 0.95) / 0.12); sqDir = sweep;
    }
    else if (tau < 1.25) { lx = d2[0]; ly = d2[1]; }
    else if (tau < 1.33) { const e = cio((tau - 1.25) / 0.08); lx = d2[0] * (1 - e); ly = d2[1] * (1 - e); }
    else if (tau < 1.45) { /* viewer, blinking */ }
    else if (tau < 1.60) { const e = cio((tau - 1.45) / 0.15); lx = d3[0] * e; ly = d3[1] * e; }
    else { lx = d3[0]; ly = d3[1]; }
    return { k, open, lx, ly, sq: 0.04 * sq, sqDir };
  }

  const C = [100, 100];
  const HEAD_REST_A = Math.atan2(35.648 - 100, 169.363 - 100); // ≈ -1.267 rad
  const RING_R = 95;
  function headPos(ts) {
    const p = lapProgress(ts);
    const theta = HEAD_REST_A - p * (4 * Math.PI); // two full laps counter-clockwise
    return [C[0] + RING_R * Math.cos(theta), C[1] + RING_R * Math.sin(theta)];
  }

  // ── Rest-phase magnet: one moving front, a spring per dot ────────────────
  //
  // Iron filings under a magnet passing overhead, but each dot is its own piece of metal.
  // A diagonal front sweeps the mark (eased, ~2.1 s). Every dot is driven by its own damped
  // spring toward a target that depends on the front's Gaussian at the dot (evaluated late
  // by the dot's `lag`), scaled by its `gain` and passed through its snap threshold `th`.
  // Stiffness `w`, damping `z` and a small lean angle `ang` also differ per dot, so
  // neighbours rise at different moments, peak at different strengths and rebound
  // differently. State (h, v) is a pure function of time since WAVE_START_S, integrated at
  // a fixed substep, so ?covert= frames are exact.
  //
  // Guard-rails: lateral shift goes through clampDisp (≤ MAX_DISP); the swell is capped at
  // SWELL_CAP and scales down where displacement is high, so neighbours never merge;
  // cyan tint is capped at 0.22 so the colour never saturates.
  const WAVE_START_S = 4.75;             // front begins just after A has settled
  const WAVE_END_S = 6.85;               //        …and clears well before A fades
  const WAVE_PITCH = 7.0;                // the shared dot pitch (ring arc ≈ 8.3, A = 7)
  const WAVE_AMP = WAVE_PITCH * 0.35;    // = 2.45 u
  const WAVE_SIGMA = 34;                 // front half-width in SVG units (soft, fat)
  const WAVE_SPAN = 170;                 // signed-distance range travelled (-85..+85)
  const WAVE_SWELL = 0.38;               // radius swell at h = 1
  const SWELL_CAP = WAVE_SWELL * 1.3;    // overshoot of the spring never swells beyond this
  const SWELL_MIN = -0.08;               // a dot may dip very slightly on the rebound
  const MAX_DISP = WAVE_AMP * 2;         // wave + pointer displacement together are clamped to this
  const ARRIVE_JIT = 1.0;                // max ring arrival jitter (lap-2 draw) per axis, units
  const WAVE_TINT = 0.22;                // cyan tint at h = 1 (secondary read)
  const WAVE_ENV_S = 0.35;               // soft in/out envelope of the front
  const SIM_DT = 1 / 240;                // fixed spring substep, s
  const SETTLE_AFTER_S = WAVE_END_S + WAVE_ENV_S + 0.6; // after this, stop once dots rest
  // Per-dot ranges (see hash seeds below).
  const LAG_MAX = 0.35, GAIN_MIN = 0.55, GAIN_MAX = 1.15, TH_MAX = 0.45;
  const W_MIN = 9, W_MAX = 16, Z_MIN = 0.32, Z_MAX = 0.6, ANG_MAX = Math.PI / 6;
  // Wave direction: a diagonal unit vector so the front sweeps across both the A and the ring.
  const WAVE_DIR_A = -Math.PI / 4;       // 45° up-right (SVG y+ is down)
  const WAVE_DX = Math.cos(WAVE_DIR_A);
  const WAVE_DY = Math.sin(WAVE_DIR_A);

  function smoothstep(a, b, x) { const t = clamp01((x - a) / (b - a)); return t * t * (3 - 2 * t); }
  function waveFront(t) { // front position along the wave direction, eased
    return -WAVE_SPAN / 2 + cio(ramp(t, WAVE_START_S, WAVE_END_S)) * WAVE_SPAN;
  }
  function waveEnv(t) {
    return Math.min(ramp(t, WAVE_START_S, WAVE_START_S + WAVE_ENV_S), ramp(WAVE_END_S - t, 0, WAVE_ENV_S));
  }
  // Stable per-dot spring parameters: k picks the parameter, seed separates ring from A.
  function springParams(dot, i, seed) {
    const hk = (k) => hash01(i * 5.31 + k * 17.9 + seed);
    dot.s = (dot.x - C[0]) * WAVE_DX + (dot.y - C[1]) * WAVE_DY; // position along the wave direction
    dot.lag = hk(1) * LAG_MAX;
    dot.gain = GAIN_MIN + hk(2) * (GAIN_MAX - GAIN_MIN);
    dot.th = hk(3) * TH_MAX;
    dot.w = W_MIN + hk(4) * (W_MAX - W_MIN);
    dot.z = Z_MIN + hk(5) * (Z_MAX - Z_MIN);
    const ang = (hk(6) * 2 - 1) * ANG_MAX;
    dot.lx = WAVE_DX * Math.cos(ang) - WAVE_DY * Math.sin(ang); // lean direction = waveDir rotated by ang
    dot.ly = WAVE_DX * Math.sin(ang) + WAVE_DY * Math.cos(ang);
    dot.h = 0; dot.v = 0;
  }

  // Worst-case distance from the mark's centre to anything painted, vs. the pad.
  function worstExtent(data) {
    let rMax = 0;
    for (const d of data.ring.concat(data.a)) {
      rMax = Math.max(rMax, Math.hypot(d.x - C[0], d.y - C[1]) + d.r * (1 + SWELL_CAP));
    }
    const dots = rMax + MAX_DISP + ARRIVE_JIT * Math.SQRT2;
    const head = RING_R + data.head.r * 1.9;
    // The head also rests at HEAD (outside the lap radius in the gap): include its halo.
    const headRest = Math.hypot(data.head.x - C[0], data.head.y - C[1]) + data.head.r * 1.9;
    // The agent's grown halo at the gap: the canvas is square, so check it per axis.
    const agent = Math.max(Math.abs(data.head.x - C[0]), Math.abs(data.head.y - C[1])) + data.head.r * 1.9 * 1.1 * AG_GROW;
    return Math.max(dots, head, headRest, agent);
  }

  // ── init ──────────────────────────────────────────────────────────────────
  function init() {
    const cover = document.querySelector(".slide.cover");
    if (!cover) return;
    const canvas = cover.querySelector(".dot-canvas");
    const data = window.APOLLO_DOTS;
    if (!canvas || !data) return;

    const params = new URLSearchParams(location.search);
    const isPresenter = !document.documentElement.hasAttribute("data-public") && params.has("presenter");
    if (isPresenter || params.has("pdf")) return; // previews and capture always use the static mark
    const reduced = matchMedia("(prefers-reduced-motion: reduce)");
    let printing = false;

    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    const extent = worstExtent(data);
    console.assert(extent <= MARK_UNITS / 2 + PAD,
      `cover-dots: worst-case extent ${extent.toFixed(2)} u exceeds the ${MARK_UNITS / 2 + PAD} u pad`);
    // Build the dot list. Ring is already in draw order (by arc-length from GAP_END).
    const ring = data.ring.map((d) => ({
      x: d.x, y: d.y, r: d.r, d: d.d,
      jx: (Math.sin(d.x * 1.37 + d.y * 0.41) * 0.5 + 0.5),
      jy: (Math.cos(d.x * 0.73 + d.y * 1.91) * 0.5 + 0.5),
    }));
    ring.forEach((d, i) => {
      springParams(d, i, 100);
      // The clear drifts each dot toward the head: onto its neighbour one step nearer the head (≈ 1 pitch).
      const toward = i > 0 ? ring[i - 1] : data.head;
      const m = Math.hypot(toward.x - d.x, toward.y - d.y) || 1, k = Math.min(1, ABSORB_MAX / m);
      d.hx = (toward.x - d.x) * k; d.hy = (toward.y - d.y) * k;
    });
    const aDots = data.a.map((d, i) => ({
      x: d.x, y: d.y, r: d.r,
      tin: A_IN_START + hash01(i * 2 + 1) * A_IN_SPREAD,
      tout: A_OUT_START + hash01(i * 2 + 7.3) * A_OUT_SPREAD,
      jx: (Math.sin(d.x * 2.11 + d.y * 0.57) * 0.5 + 0.5),
      jy: (Math.cos(d.x * 0.91 + d.y * 2.33) * 0.5 + 0.5),
    }));
    aDots.forEach((d, i) => springParams(d, i, 500));
    const springDots = ring.concat(aDots); // one flat list, stepped together

    // Look directions (unit vectors from the head): down-left to the mark's centre (where the A was),
    // to the ring's bottom-right (the gap's lower lip, where the ring ended), and along the lap
    // direction (counter-clockwise on screen, i.e. up-left at the head).
    function unit(x, y) { const m = Math.hypot(x, y) || 1; return [x / m, y / m]; }
    const lookDown = unit(C[0] - data.head.x, C[1] - data.head.y);
    const lipAngle = Math.PI / 6; // 4 o'clock
    const lookSweep = unit(C[0] + RING_R * Math.cos(lipAngle) - data.head.x, C[1] + RING_R * Math.sin(lipAngle) - data.head.y);
    const headAngle = Math.atan2(data.head.y - C[1], data.head.x - C[0]);
    const lookLap = [Math.sin(headAngle), -Math.cos(headAngle)];

    // Sizing. W/H are the canvas's layout size in stage pixels (offsetWidth ignores the stage's
    // CSS scale; pointer maths uses S with the on-screen rect below). The backing store is
    // sized to the *on-screen* pixels (layout size × stage scale × devicePixelRatio, capped at
    // MAX_BACKING px per side) so the mark stays crisp when the 1920 stage is scaled up on a
    // large or high-DPI screen. RES = backing px per stage px.
    const MAX_BACKING = 2048;
    let W = 0, H = 0, S = 1, RES = DPR;
    function fit() {
      const lw = canvas.offsetWidth || 1, lh = canvas.offsetHeight || 1;
      const rect = canvas.getBoundingClientRect();
      const stageScale = rect.width / lw || 1;                    // CSS scale applied by deck.js
      const dpr = window.devicePixelRatio || 1;
      W = lw; H = lh;
      S = Math.min(rect.width, rect.height) / PX_IN_SVG;          // on-screen px per SVG unit (pointer)
      RES = Math.min(stageScale * dpr, MAX_BACKING / Math.max(W, H));
      const bw = Math.round(W * RES), bh = Math.round(H * RES);
      if (canvas.width !== bw || canvas.height !== bh) { canvas.width = bw; canvas.height = bh; }
    }
    fit();
    // Refit when the canvas or the window changes size (the stage scale follows the window),
    // or when the page moves to a screen with a different devicePixelRatio.
    const refit = () => { fit(); if (COVERT !== null && running) draw(COVERT, 16); };
    new ResizeObserver(refit).observe(canvas);
    addEventListener("resize", refit);
    (function watchDpr() {
      const mq = matchMedia(`(resolution: ${window.devicePixelRatio || 1}dppx)`);
      mq.addEventListener("change", () => { refit(); watchDpr(); }, { once: true });
    })();

    // Pointer magnet: pulls dots toward the cursor during rest, with a short decay after
    // the pointer leaves so the influence melts away instead of snapping.
    let ptrX = -999, ptrY = -999, ptrDecay = 0;
    canvas.addEventListener("pointermove", (e) => {
      const rect = canvas.getBoundingClientRect();
      ptrX = (e.clientX - rect.left) / S - PAD;
      ptrY = (e.clientY - rect.top) / S - PAD;
      ptrDecay = 1;
    });
    canvas.addEventListener("pointerleave", () => { ptrDecay = 0; });

    function pointerField(x, y, fade) {
      // Soft pointer attractor during rest. Capped to WAVE_AMP so it stays within the
      // same displacement budget as the shimmer wave (no overlap, no collision).
      if (ptrDecay <= 0 || ptrX < -500) return { dx: 0, dy: 0, lift: 0 };
      const dx = ptrX - x, dy = ptrY - y;
      const d2 = dx * dx + dy * dy;
      const pull = Math.exp(-d2 / (2 * 20 * 20));
      const inv = pull > 1e-6 ? 1 / Math.sqrt(d2 + 1e-6) : 0;
      const amp = WAVE_AMP * ptrDecay * fade;
      return { dx: dx * inv * pull * amp, dy: dy * inv * pull * amp, lift: pull * ptrDecay * fade };
    }

    let raf = 0, startTs = 0, running = false, lastFrame = 0;
    function visibleAndActive() {
      return cover.classList.contains("is-active") && !document.hidden && !printing && !reduced.matches;
    }
    function start() {
      if (running) return;
      running = true;
      if (COVERT !== null) { // debug freeze: one deterministic frame, no animation
        canvas.classList.add("live");
        draw(COVERT, 16);
        return;
      }
      startTs = performance.now() - FIRST_VISIT_TS * 1000;
      lastFrame = startTs;
      raf = requestAnimationFrame(frame);
      canvas.classList.add("live");
    }
    function stop() {
      if (!running) return;
      running = false;
      cancelAnimationFrame(raf);
      canvas.classList.remove("live");
      ctx.clearRect(0, 0, canvas.width, canvas.height);
    }
    function frame(now) {
      if (!visibleAndActive()) { stop(); return; }
      const dt = Math.max(1, Math.min(64, now - lastFrame));
      lastFrame = now;
      const tms = (now - startTs) % CYCLE;
      draw(tms / 1000, dt);
      raf = requestAnimationFrame(frame);
    }

    function clampDisp(dx, dy) {
      const m = Math.hypot(dx, dy);
      return m > MAX_DISP ? [dx * MAX_DISP / m, dy * MAX_DISP / m] : [dx, dy];
    }

    // Spring state for every ring/A dot: h = how far it has risen toward the magnet, v = its
    // velocity. Pure function of the time since WAVE_START_S: a backwards jump (loop wrap or
    // ?covert=) or ts before the start resets it, then it is stepped forward at SIM_DT.
    let simT = WAVE_START_S, simRest = true;
    function resetSprings() {
      for (let i = 0; i < springDots.length; i++) { springDots[i].h = 0; springDots[i].v = 0; }
      simT = WAVE_START_S;
      simRest = true;
    }
    function stepSprings(ts) {
      if (ts < simT - SIM_DT || ts < WAVE_START_S) { resetSprings(); if (ts < WAVE_START_S) return; }
      if (simRest && simT > SETTLE_AFTER_S) { simT = ts; return; } // settled: h = v = 0
      simRest = false;
      while (simT < ts) {
        const t = simT;
        for (let i = 0; i < springDots.length; i++) {
          const p = springDots[i];
          const tl = t - p.lag;
          const s = p.s - waveFront(tl);
          const g = Math.exp(-(s * s) / (2 * WAVE_SIGMA * WAVE_SIGMA));
          const target = p.gain * smoothstep(p.th, 1, g) * waveEnv(tl);
          p.v += (p.w * p.w * (target - p.h) - 2 * p.z * p.w * p.v) * SIM_DT;
          p.h += p.v * SIM_DT;
        }
        simT += SIM_DT;
      }
      if (simT > SETTLE_AFTER_S) {
        let rest = true;
        for (let i = 0; i < springDots.length && rest; i++) {
          rest = Math.abs(springDots[i].h) < 1e-3 && Math.abs(springDots[i].v) < 1e-3;
        }
        if (rest) { for (let i = 0; i < springDots.length; i++) { springDots[i].h = 0; springDots[i].v = 0; } simRest = true; }
      }
    }

    // Wave response of one dot: lateral shift (before clamping), radius swell and tint level.
    const resp = { dx: 0, dy: 0, swell: 0, tint: 0 };
    function waveResponse(p) {
      const k = p.h * WAVE_AMP * 0.7;
      resp.dx = p.lx * k;
      resp.dy = p.ly * k;
      resp.swell = Math.min(SWELL_CAP, Math.max(SWELL_MIN, WAVE_SWELL * p.h));
      resp.tint = Math.max(0, p.h);
    }

    function mix(a, b, t) {
      return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];
    }

    function draw(ts, dt) {
      if (ptrDecay > 0) ptrDecay = Math.max(0, ptrDecay - dt / 300);

      const drawn = ringDrawn(ts);
      const cleared = ringClear(ts);
      const restActive = ts >= WAVE_START_S && drawn >= 1 && cleared <= 0.001;
      stepSprings(ts);
      // Pointer magnet: from the wave start until the A dissolve begins (short fade into it).
      const ptrFade = ts >= WAVE_START_S ? ramp(A_OUT_START - ts, 0, 0.3) : 0;

      ctx.setTransform(1, 0, 0, 1, 0, 0);
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      const scale = (Math.min(W, H) / PX_IN_SVG) * RES;
      const ox = (W * RES - PX_IN_SVG * scale) / 2 + PAD * scale;
      const oy = (H * RES - PX_IN_SVG * scale) / 2 + PAD * scale;
      ctx.setTransform(scale, 0, 0, scale, ox, oy);
      const stats = COVERT !== null ? { ts, extent, litRing: 0, litFar: 0, litNear: 0, litA: 0, front: waveFront(ts), dots: [] } : null;

      // Soft lattice-ghost: shows the ring's underlying structure even before it draws,
      // so the mark reads as "a dot matrix at rest, waiting to be lit", not as empty space.
      ctx.fillStyle = "rgba(170, 203, 255, 0.08)"; // constant: identical at t = 11.6 and t = 0
      for (let i = 0; i < ring.length; i++) {
        const p = ring[i];
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.r * 0.6, 0, Math.PI * 2);
        ctx.fill();
      }

      // ── Ring dots ───────────────────────────────────────────────────────────
      for (let i = 0; i < ring.length; i++) {
        const p = ring[i];
        let lit = Math.max(0, Math.min(1, (drawn - p.d) * 18));
        // Reel-in: the front runs from the far end (d = 1) back to the head (d = 0), so a dot is gone
        // once the front passes 1 − d. `gone` is that progress, 0..1.
        let gone = 0;
        if (cleared > 0) {
          gone = 1 - clamp01(((1 - p.d) - cleared) * 18 + 1);
          lit *= cio(1 - gone); // eased fade-out
        }
        if (lit <= 0.001) continue;
        if (stats && lit > 0.05) { stats.litRing++; if (p.d > 0.5) stats.litFar++; else stats.litNear++; }

        // Arrival jitter during the lap-2 draw: dot pulled from a small offset and settles.
        const front = Math.max(0, 1 - Math.abs(drawn - p.d) * 12);
        const jit = (1 - lit) * 2.0;
        let jx = (p.jx - 0.5) * jit * front;
        let jy = (p.jy - 0.5) * jit * front;

        let swell = 0, tint = 0;
        if (restActive) {
          waveResponse(p);
          const pm = pointerField(p.x, p.y, ptrFade);
          [jx, jy] = clampDisp(jx + resp.dx + pm.dx, jy + resp.dy + pm.dy);
          swell = Math.max(resp.swell, WAVE_SWELL * pm.lift);
          tint = Math.max(resp.tint, pm.lift);
          if (stats) stats.dots.push([p.s, p.h, p.x + jx, p.y + jy, p.r * (1 + swell)]);
        }
        // Scale the swell down where displacement is high so a fat dot can't overlap a
        // shifted neighbour's edge ('keep the swell from pushing neighbours together').
        const dispN = Math.min(1, Math.hypot(jx, jy) / WAVE_AMP);
        swell *= 1 - 0.25 * dispN;
        // Absorbed: drift toward the head (≤ 1 pitch, ease-in) while shrinking.
        const absorb = easeIn2(gone);
        jx += p.hx * absorb; jy += p.hy * absorb;
        const col = mix(COL_WHITE, COL_CYAN, WAVE_TINT * tint);
        ctx.fillStyle = `rgba(${col[0]|0},${col[1]|0},${col[2]|0},${lit})`;
        ctx.beginPath();
        ctx.arc(p.x + jx, p.y + jy, p.r * (1 + swell) * (1 - 0.5 * gone), 0, Math.PI * 2);
        ctx.fill();
      }

      // ── A dots ──────────────────────────────────────────────────────────────
      // Each dot has its own arrival (p.tin) and departure (p.tout) moment.
      if (ts >= A_IN_START && ts <= A_OUT_START + A_OUT_SPREAD + A_OUT_DUR) {
        for (let i = 0; i < aDots.length; i++) {
          const p = aDots[i];
          const kin = clamp01((ts - p.tin) / A_IN_DUR);
          const kout = clamp01((ts - p.tout) / A_OUT_DUR);
          const alpha = cio(kin) * (1 - kout * kout);
          if (alpha <= 0.002) continue;
          if (stats && alpha > 0.05) stats.litA++;
          // Pop in with a small spring overshoot; shrink away on the way out.
          const rScale = (0.35 + 0.65 * backOut(kin)) * (1 - 0.7 * kout * kout);

          let jx = 0, jy = 0, swell = 0, tint = 0;
          if (restActive) {
            waveResponse(p);
            const pm = pointerField(p.x, p.y, ptrFade);
            [jx, jy] = clampDisp(resp.dx + pm.dx, resp.dy + pm.dy);
            swell = Math.max(resp.swell, WAVE_SWELL * pm.lift);
            tint = Math.max(resp.tint, pm.lift);
            if (stats) stats.dots.push([p.s, p.h, p.x + jx, p.y + jy, p.r * (1 + swell)]);
          }
          // Settle into place from a small offset as the dot arrives.
          const settle = 1 - cio(kin);
          jx += (p.jx - 0.5) * settle * 3.0;
          jy += (p.jy - 0.5) * settle * 3.0;

          const dispN = Math.min(1, Math.hypot(jx, jy) / WAVE_AMP);
          swell *= 1 - 0.25 * dispN;
          const col = mix(COL_WHITE, COL_CYAN, WAVE_TINT * tint);
          ctx.fillStyle = `rgba(${col[0]|0},${col[1]|0},${col[2]|0},${alpha})`;
          ctx.beginPath();
          ctx.arc(p.x + jx, p.y + jy, p.r * (1 + swell) * rScale, 0, Math.PI * 2);
          ctx.fill();
        }
      }

      // ── Head dot ────────────────────────────────────────────────────────────
      const [hx, hy] = headPos(ts);
      const trail = (ts > 0.5 && ts < 4.3)
        ? Math.min(1, Math.min((ts - 0.5) / 0.6, (4.3 - ts) / 0.5))
        : 0;
      if (trail > 0.01) {
        for (let k = 1; k <= 14; k++) {
          const back = k * 0.055;
          const past = Math.max(0, ts - back);
          const [tx, ty] = headPos(past);
          const a = (1 - k / 15) * 0.65 * trail;
          const rr = 4.6 - k * 0.22;
          if (rr <= 0.2) break;
          ctx.fillStyle = `rgba(170, 203, 255, ${a.toFixed(3)})`;
          ctx.beginPath();
          ctx.arc(tx, ty, rr, 0, Math.PI * 2);
          ctx.fill();
        }
      }
      const headR = data.head.r;
      const ag = agentState(ts, lookDown, lookSweep, lookLap);
      const gulp = swallow(ts);
      if (!ag) {
        const gr = headR * (1 + SWALLOW_R * gulp);
        ctx.fillStyle = `rgba(170, 203, 255, ${(0.28 + 0.22 * gulp).toFixed(4)})`;
        ctx.beginPath();
        ctx.arc(hx, hy, gr * 1.9, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = "#fff";
        ctx.beginPath();
        ctx.arc(hx, hy, gr, 0, Math.PI * 2);
        ctx.fill();
      } else {
        const R = headR * ag.k;
        // Halo scales with the orb and gets softer: its rim fades as the orb grows.
        const soft = clamp01((ag.k - 1) / (AG_GROW - 1));
        const halo = ctx.createRadialGradient(hx, hy, R, hx, hy, R * 1.9);
        halo.addColorStop(0, "rgba(170, 203, 255, 0.28)");
        halo.addColorStop(1, `rgba(170, 203, 255, ${(0.28 * (1 - 0.85 * soft)).toFixed(4)})`);
        ctx.fillStyle = halo;
        ctx.beginPath();
        ctx.arc(hx, hy, R * 1.9, 0, Math.PI * 2);
        ctx.fill();
        ctx.save();
        ctx.translate(hx, hy);
        const sa = Math.atan2(ag.sqDir[1], ag.sqDir[0]);
        ctx.rotate(sa); ctx.scale(1 - ag.sq, 1 + ag.sq * 0.5); ctx.rotate(-sa); // squash toward the glance
        ctx.fillStyle = "#fff";
        ctx.beginPath();
        ctx.arc(0, 0, R, 0, Math.PI * 2);
        ctx.fill();
        if (ag.open > 0.004) {
          ctx.clip(); // eyes stay inside the orb
          const u = ag.k / AG_GROW; // eye geometry scales with the orb
          const sx = Math.max(-1, Math.min(1, ag.lx / AG_LOOK)); // sideways look, -1..1
          ctx.fillStyle = AG_EYE_COL;
          for (const side of [-1, 1]) {
            // The leading eye is ~10% narrower on sideways looks (a hint of perspective).
            const w = AG_EYE_W * u * (side * sx > 0 ? 1 - 0.1 * Math.abs(sx) : 1);
            const h = AG_EYE_H * u;
            const cx = (side * AG_EYE_GAP / 2 + ag.lx) * u;
            const cy = (AG_EYE_DY + ag.ly) * u;
            ctx.save();
            ctx.translate(cx, cy);
            ctx.scale(1, ag.open);
            ctx.beginPath();
            ctx.moveTo(-w / 2, -h / 2 + w / 2);
            ctx.arc(0, -h / 2 + w / 2, w / 2, Math.PI, 0);
            ctx.lineTo(w / 2, h / 2 - w / 2);
            ctx.arc(0, h / 2 - w / 2, w / 2, 0, Math.PI);
            ctx.closePath();
            ctx.fill();
            ctx.restore();
          }
        }
        ctx.restore();
      }
      if (stats) { window.__coverStats = stats; canvas.dataset.covertStats = JSON.stringify(stats); }
    }

    function sync() { if (visibleAndActive()) start(); else stop(); }
    const mo = new MutationObserver(sync);
    mo.observe(cover, { attributes: true, attributeFilter: ["class"] });
    document.addEventListener("visibilitychange", sync);
    reduced.addEventListener("change", sync);
    addEventListener("beforeprint", () => { printing = true; sync(); });
    addEventListener("afterprint", () => { printing = false; sync(); });
    sync();
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }
})();
